// RestMethodsToEnvVar converts RestMethods to environment variable key-value pairs.
func RestMethodsToEnvVar(v *RestMethods) map[string]string {
	if v == nil {
		return nil
	}
	result := make(map[string]string)
	if len(v.Methods) > 0 {
		parts := make([]string, len(v.Methods))
		for i, val := range v.Methods {
			parts[i] = RestMethodToString(val)
		}
		result["PROTO_LIBS_SPEC_REST_METHODS_METHODS"] = strings.Join(parts, ",")
	}
	return result
}

// RestMethodsFromEnvVar creates RestMethods from environment variable key-value pairs.
func RestMethodsFromEnvVar(env map[string]string) (*RestMethods, error) {
	result := &RestMethods{}
	if val, ok := env["PROTO_LIBS_SPEC_REST_METHODS_METHODS"]; ok && val != "" {
		parts := strings.Split(val, ",")
		result.Methods = make([]RestMethod, 0, len(parts))
		for _, p := range parts {
			parsed, err := ParseRestMethod(strings.TrimSpace(p))
			if err != nil {
				return nil, err
			}
			result.Methods = append(result.Methods, parsed)
		}
	}
	return result, nil
}

